// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }

    // Fuzz the callee selector to ensure calldata can be arbitrary; we deploy two helper callees:
    // - Reverter: always reverts on fallback() to simulate a failing callee
    // - Succeeder: accepts calls and returns success
    // The general rule: for any callee, forward() should succeed (not revert) iff the low-level call to callee succeeds.
    // We fuzz a boolean chooseReverter to pick which helper to call; the fuzzer drives that and thus will find the case
    // where the mutant flips the require and thus changes whether forward() reverts.
    function testFuzz_property(bool chooseReverter) public {
        // Deploy adversarial helpers
        Reverter rev = new Reverter();
        Succeeder suc = new Succeeder();

        address callee = chooseReverter ? address(rev) : address(suc);

        // Prepare arbitrary calldata: call a 4-byte selector that Succeeder recognizes (recordAndReturn)
        // and Reverter will just revert regardless of data. Fuzzer controls chooseReverter only; calldata
        // can be arbitrary since forward takes bytes. We encode a valid call to the recording function so
        // Succeeder will succeed when chosen.
        bytes memory data = abi.encodeWithSelector(Succeeder.recordAndReturn.selector, uint256(12345));

        // Call forward and record whether it reverted via try/catch
        bool ok;
        try c.forward(callee, data) {
            ok = true;
        } catch {
            ok = false;
        }

        // The correct contract: forward should succeed (ok == true) when callee is Succeeder, and revert (ok == false)
        // when callee is Reverter. This is a universal property over the fuzzed boolean chooseReverter.
        if (chooseReverter) {
            // calling the reverter should make forward revert
            assertTrue(!ok);
        } else {
            // calling the succeeder should make forward succeed
            assertTrue(ok);
        }
    }
}

// Helper that always reverts on any call
contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}

// Helper that records calls and returns success
contract Succeeder {
    uint256 public lastArg;
    uint256 public calls;

    // Match the selector we use in the test so calldata is well-formed ABI and the call succeeds
    function recordAndReturn(uint256 x) external payable returns (bool) {
        lastArg = x;
        calls += 1;
        return true;
    }

    fallback() external payable {
        // accept any other calls and succeed
        calls += 1;
    }
    receive() external payable {}
}
